	cmd63 := &cli.Command{Name: "use", Usage: "Add bootstrap packages to [bootstrap.packages] and install them", Description: "Add bootstrap packages to [bootstrap.packages] and install them\n\nLike `mise use` for tools: writes `\"manager:package\" = \"version\"` entries to mise.toml (the local config by default, the global one with `-g`) and then installs whatever is missing.\n\nVersions are pinned with `@`: `mise bootstrap packages use apt:curl@8.5.0-2`. Without `@` (or with `@latest`) no pin is written. brew formulae and casks version through their names instead (for example `brew:postgresql@17`, `brew-cask:temurin@17`), where `@` is part of the Homebrew name rather than a mise version selector. mas uses numeric ADAM IDs and does not support pins.", Aliases: []string{"u"}, Action: reached, Flags: []cli.Flag{&cli.StringFlag{Name: "env", Aliases: []string{"e"}, Usage: "Write to the config file for this environment (mise.<ENV>.toml)", Local: true}, &cli.BoolFlag{Name: "global", Aliases: []string{"g"}, Usage: "Write to the global config (~/.config/mise/config.toml) instead of the local one", Local: true}, &cli.BoolFlag{Name: "dry-run", Aliases: []string{"n"}, Usage: "Print the commands that would run without writing config or installing", Local: true}, &cli.StringFlag{Name: "path", Aliases: []string{"p", "file"}, Usage: "Write to this config file or directory", Local: true}, &cli.BoolFlag{Name: "yes", Aliases: []string{"y"}, Usage: "Skip the confirmation prompt", Local: true}}, Arguments: []cli.Argument{&cli.StringArgs{Name: "PACKAGE", Min: 1, Max: -1}}}
