	cmd158 := &cli.Command{Name: "prune", Usage: "Delete unused versions of tools", Description: "Delete unused versions of tools\n\nmise tracks which config files have been used in ~/.local/state/mise/tracked-configs Versions which are no longer the latest specified in any of those configs are deleted. Versions installed only with environment variables `MISE_<TOOL>_VERSION` will be deleted, as will versions only referenced on the command line `mise exec <TOOL>@<VERSION>`.\n\nTool stubs that have been executed are tracked in ~/.local/state/mise/tracked-stubs. Versions still referenced by a tracked stub are not deleted.\n\nYou can list prunable tools with `mise ls --prunable`", Action: reached, Flags: []cli.Flag{&cli.BoolFlag{Name: "dry-run", Aliases: []string{"n"}, Usage: "Do not actually delete anything", Local: true}, &cli.BoolFlag{Name: "configs", Usage: "Prune only tracked and trusted configuration links that point to nonexistent configurations", Local: true}, &cli.BoolFlag{Name: "dry-run-code", Usage: "Like --dry-run but exits with code 1 if there are tools to prune", Local: true}, &cli.BoolFlag{Name: "monorepo", Usage: "Placeholder for future monorepo pruning; `mise prune --monorepo` is not implemented yet.", Local: true}, &cli.BoolFlag{Name: "tools", Usage: "Prune only unused versions of tools", Local: true}}, Arguments: []cli.Argument{&cli.StringArgs{Name: "INSTALLED_TOOL", Min: 0, Max: -1}}}
