	cmd198 := &cli.Command{Name: "tool-stub", Usage: "Execute a tool stub", Description: "Execute a tool stub\n\nTool stubs are executable files containing TOML configuration that specify which tool to run and how to run it. They provide a convenient way to create portable, self-contained executables that automatically manage tool installation and execution.\n\nA tool stub consists of: - A shebang line: #!/usr/bin/env -S mise tool-stub - TOML configuration specifying the tool, version, and options - Optional comments describing the tool's purpose\n\nExample stub file:\n  #!/usr/bin/env -S mise tool-stub\n  # Node.js v20 development environment\n\n  tool = \"node\"\n  version = \"20.0.0\"\n  bin = \"node\"\n\nThe stub will automatically install the specified tool version if missing and execute it with any arguments passed to the stub.\n\nFor more information, see: https://mise.jdx.dev/dev-tools/tool-stubs.html", Action: reached, Arguments: []cli.Argument{&cli.StringArg{Name: "FILE"}, &cli.StringArgs{Name: "ARGS", Min: 0, Max: -1}}}
	cmd199 := &cli.Command{Name: "trust", Usage: "Marks a config file as trusted", Description: "Marks a config file as trusted\n\nThis means mise is allowed to parse the file when it needs to read config that may execute code or affect the environment. Without trust, mise may prompt, skip the config in some discovery paths, or fail with an untrusted-config error when it cannot prompt.\n\nIn normal mode, commands that execute project-defined behavior (`mise run`, naked task invocations such as `mise <TASK>`, `mise install`, `mise exec`, and `mise watch`) automatically trust their active config. Paranoid mode requires explicit, content-bound trust for every non-global config.\n\nIn normal mode, safe config files do not require trust: files that only contain `min_version`, `[tools]` entries with plain version strings (or arrays of them), and `[tasks]` without templates or tool options.\n\nTrust is shared across git worktrees: a config file inside a linked worktree is trusted when the equivalent path in the repository's main checkout has been trusted. Paranoid mode disables this sharing since worktrees can check out branches with different config contents.", Action: reached, Flags: []cli.Flag{&cli.BoolFlag{Name: "all", Aliases: []string{"a"}, Usage: "Trust all config files in the current directory, its parents, and its subdirectories", Local: true}, &cli.BoolFlag{Name: "ignore", Usage: "Do not trust this config and ignore it in the future", Local: true}, &cli.BoolFlag{Name: "show", Usage: "Show the trusted status of config files from the current directory and its parents.\nDoes not trust or untrust any files.", Local: true}, &cli.BoolFlag{Name: "untrust", Usage: "Remove explicit trust for this config", Local: true}}, Arguments: []cli.Argument{&cli.StringArg{Name: "CONFIG_FILE"}}}
	cmd200 := &cli.Command{Name: "uninstall", Usage: "Removes installed tool versions", Description: "Removes installed tool versions\n\nThis only removes the installed version, it does not modify mise.toml.", Action: reached, Flags: []cli.Flag{&cli.BoolFlag{Name: "all", Aliases: []string{"a"}, Usage: "Delete all installed versions", Local: true}, &cli.BoolFlag{Name: "dry-run", Aliases: []string{"n"}, Usage: "Do not actually delete anything", Local: true}, &cli.BoolFlag{Name: "dry-run-code", Usage: "Like --dry-run but exits with code 1 if there are tools to uninstall", Local: true}}, Arguments: []cli.Argument{&cli.StringArgs{Name: "INSTALLED_TOOL@VERSION", Min: 0, Max: -1}}}
